enum Nsp405Reg {
  TCP0 = 0,
  TCP14 = 14,
  SCR = 16,
  VCR = 17,
  HOME = 18,
  BEGD = 20,
  ENDD = 22,
  SROW = 24,
  AL0 = 26,
  AL1 = 27,
  CURS = 28,
  ROW_PTR0 = 30,
  ROW_PTR1 = 31,
  ROW_PTR24 = 54,
  XSCROLL = 55,
}

export const XEP80_RAM_SIZE = 8192;
export const XEP80_REGS_SIZE = 64;
export const XEP80_STATE_SIZE = XEP80_RAM_SIZE + XEP80_REGS_SIZE;

export function decodeXep80Update(data: Uint8Array, state: Uint8Array): void {
  let idx = 0;
  let addr = 0;

  const writeByte = (value: number) => {
    if (addr >= 0 && addr < XEP80_STATE_SIZE) {
      state[addr] = value & 0xFF;
    }
    addr += 1;
  };

  while (idx < data.length) {
    const cmd = data[idx++];
    if (cmd === 0xFF) {
      break;
    }

    const op = cmd & 0xF0;
    const low = cmd & 0x0F;

    switch (op) {
      case 0x80: { // 8X YY - repeat byte YY for X + 1 times
        if (idx >= data.length) return;
        const value = data[idx++];
        const count = low + 1;
        for (let i = 0; i < count; i++) {
          writeByte(value);
        }
        break;
      }
      case 0x90: { // 9X XX YY - repeat byte YY for XXX + 1 times
        if (idx + 1 >= data.length) return;
        const count = ((low << 8) | data[idx++]) + 1;
        const value = data[idx++];
        for (let i = 0; i < count; i++) {
          writeByte(value);
        }
        break;
      }
      case 0xA0: { // AX - literal copy next X + 1 bytes
        const count = low + 1;
        for (let i = 0; i < count; i++) {
          if (idx >= data.length) return;
          writeByte(data[idx++]);
        }
        break;
      }
      case 0xB0: { // BX XX - literal copy next XXX + 1 bytes
        if (idx >= data.length) return;
        const count = ((low << 8) | data[idx++]) + 1;
        for (let i = 0; i < count; i++) {
          if (idx >= data.length) return;
          writeByte(data[idx++]);
        }
        break;
      }
      default:
        if ((op & 0x80) == 0) {
          if (idx >= data.length) return;
          addr = ((op + low) << 8) | data[idx++];
          break;
        }
        // Invalid command, ignore and continue
        return;
    }
  }
}

export interface WorkerMessage {
  type: string;
  canvas?: OffscreenCanvas;
  state?: Uint8Array;
}

let fonts: Array<ImageBitmap | null> = [];
let offscreenCanvas: OffscreenCanvas | null = null;
let ctx: OffscreenCanvasRenderingContext2D | null = null;

// Font bitmap: 128 characters in 16x8 matrix, each character 8x12 pixels
const FONT_CHAR_WIDTH = 8;
const FONT_CHAR_HEIGHT = 12;
const FONT_COLS = 16;

// Canvas: 560x250 pixels = 80x25 characters, each 7x10 pixels
const DISP_CHAR_WIDTH = 7;
const DISP_CHAR_HEIGHT = 10;
const DISP_COLS = 80;
const DISP_ROWS = 25;

async function loadFont(url: string): Promise<ImageBitmap | null> {
  try {
    const response = await fetch(new URL(url, import.meta.url));
    const blob = await response.blob();
    return await createImageBitmap(blob);
  } catch (err) {
    console.error("Failed to load font_normal.png:", err);
    return null;
  }
}

type CharAttr = {
  inverted: boolean;
  doubleWidth: boolean;
  doubleHeight: boolean;
  bottomHalf?: boolean;
  font: ImageBitmap;
}

function drawCharacter(ctx: OffscreenCanvasRenderingContext2D, charCode: number, x: number, y: number, attr: CharAttr) {
  // Calculate source position in font bitmap
  const col = charCode % FONT_COLS;
  const row = Math.floor(charCode / FONT_COLS);

  const sx = col * FONT_CHAR_WIDTH;
  let sy = row * FONT_CHAR_HEIGHT;
  let sh = DISP_CHAR_HEIGHT;

  if (attr.doubleHeight) {
    sh = DISP_CHAR_HEIGHT / 2;
    if (attr.bottomHalf) {
      sy += DISP_CHAR_HEIGHT / 2;
    }
  }

  let w = DISP_CHAR_WIDTH;

  if (attr.doubleWidth) {
    w = DISP_CHAR_WIDTH * 2;
  }

  // Draw character from font bitmap to canvas
  ctx.filter = attr.inverted ? 'invert(1)' : 'none';
  ctx.imageSmoothingEnabled = false;

  ctx.drawImage(
    attr.font,
    sx, sy, DISP_CHAR_WIDTH, sh,   // source rect
    x, y, w, DISP_CHAR_HEIGHT      // dest rect
  );

  ctx.filter = 'none';
  ctx.imageSmoothingEnabled = true;
}


function drawCursor(ctx: OffscreenCanvasRenderingContext2D, x: number, y: number) {
  ctx.save();
  ctx.fillStyle = "green";
  ctx.globalCompositeOperation = "difference";
  ctx.fillRect(x, y, DISP_CHAR_WIDTH, DISP_CHAR_HEIGHT);
  ctx.restore();
}



self.onmessage = async (event: MessageEvent<WorkerMessage>) => {
  const { type, canvas, state } = event.data;

  if (type === "init" && canvas) {
    // Store canvas and context for reuse
    offscreenCanvas = canvas;
    ctx = canvas.getContext("2d");

    // Load font bitmap first
    fonts[0] = await loadFont("../assets/font_internal.png");
    fonts[1] = await loadFont("../assets/font_normal.png");
    fonts[2] = await loadFont("../assets/font_international.png");
  }

  if (ctx && state) {
    renderFramebuffer(state, ctx);
  }
};

function renderFramebuffer(state: Uint8Array, ctx: OffscreenCanvasRenderingContext2D) {

  const ram = state.subarray(0, XEP80_RAM_SIZE);
  const regs = state.subarray(XEP80_RAM_SIZE, XEP80_STATE_SIZE);

  const opt = {
    home: 0,
    begd: 0,
    endd: 0x1800,
    curs: regs[Nsp405Reg.CURS] + regs[Nsp405Reg.CURS + 1] * 256,
    srow: 0x1700,

    attr: [{
      inverted: false,
      blinking: false,
      doubleWidth: false,
      doubleHeight: false,
      blank: false,
    },
    {
      inverted: true,
      blinking: false,
      doubleWidth: false,
      doubleHeight: false,
      blank: true,
    }],

    invertedScreen: false,
    invertedCursor: false,
    blinkingCursor: false,
    blinkingField: false,

    rows: regs.subarray(Nsp405Reg.ROW_PTR0, Nsp405Reg.ROW_PTR0 + DISP_ROWS),
    colOfs: regs[Nsp405Reg.XSCROLL],
  };

  // Each character in framebuffer is represented by one byte
  // Framebuffer size should be 80 * 24 = 1920 bytes
  // 7th bit of each byte is unused

  // Clear canvas
  ctx.fillStyle = opt.invertedScreen ? "white" : "black";
  ctx.fillRect(0, 0, 560, 250);

  // Draw characters from framebuffer
  for (let row = 0; row < DISP_ROWS; row++) {
    const rowOfs = (opt.rows[row] & 0x1F) * 256 + opt.colOfs;
    const font = fonts[(opt.rows[row] >> 5) & 0x03];

    if (font === null) {
      continue;
    }

    for (let col = 0; col < DISP_COLS; col++) {
      const ofs = rowOfs + col;

      let attr;
      let char;

      if (ram[ofs] != 0x9B) {
        attr = opt.attr[ram[ofs] & 0x80 ? 1 : 0];
        char = ram[ofs] & 0x7F;
      } else {
        attr = opt.attr[0];
        char = 0x20;
      }

      const x = col * DISP_CHAR_WIDTH;
      const y = row * DISP_CHAR_HEIGHT;

      const charAttr: CharAttr = {
        font: font,
        inverted: attr.inverted !== opt.invertedScreen,
        doubleWidth: attr.doubleWidth,
        doubleHeight: attr.doubleHeight,
        bottomHalf: attr.doubleHeight && attr.blank,
      }

      drawCharacter(ctx, char, x, y, charAttr);

      if (ofs === opt.curs) {
        drawCursor(ctx, x, y);
      }

      if (attr.doubleWidth) {
        col += 1
      }
    }
  }

  self.postMessage({ type: "rendered" });
}
